using System;
using System.Reflection;
namespace Downfield {
public static class OnsideTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Onside: "+name);}}
 static void Call(Simulation s,string name,params object[] args){typeof(Simulation).GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic,null,Array.ConvertAll(args,a=>a.GetType()),null).Invoke(s,args);}
 static Simulation Try(int seed){Simulation s=new Simulation(seed);s.RequestOnsideTry();s.ConfirmOnsideTry();return s;}
 public static int Run(){checks=failures=0;Simulation s=new Simulation(1);float clock=s.Clock;Check(s.RequestOnsideTry()&&s.OnsideRulesPending&&!s.OnsideAttempt,"first request opens explanation before play");s.Snap();s.Update(.05f,0,1);Check(s.State==Phase.PreSnap&&s.Clock==clock,"rules popup freezes play and clock");s.ConfirmOnsideTry();Check(s.OnsideAttempt&&s.Spot==30&&s.Down==4&&s.FirstDown==43,"try sets fourth and thirteen from own thirty");Check(s.OnsideAttempts==1&&!s.CanOnsideTry,"cannot chain another try before resolving it");s.Punt();s.FieldGoal();Check(s.State==Phase.PreSnap&&!s.SimDrive(),"try cannot be replaced by kick or whole simulated drive");s.Snap();Check(s.State==Phase.Live&&s.Down==4,"try uses normal live gameplay");Call(s,"EndPlay",43f,"OUT: 13 YDS",false);Check(s.State==Phase.Dead&&!s.OnsideAttempt&&s.Down==1&&s.Spot==43&&s.FirstDown==53,"thirteen yards keeps possession at gain spot");Check(s.OnsideConversions==1&&s.Clock==clock,"out of bounds conversion stops clock normally");s.Next();Check(s.RequestOnsideTry()&&!s.OnsideRulesPending&&s.OnsideAttempt&&s.OnsideAttempts==2,"later attempt needs no repeated explanation or attempt limit");
  s=Try(2);s.Snap();Call(s,"EndPlay",42.9f,"TACKLED",false);Check(s.State==Phase.Opponent&&!s.OnsideAttempt&&s.LastPlay=="TURNOVER ON DOWNS","short gain immediately turns over");float start=(float)typeof(Simulation).GetField("opponentStart",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s);Check(Math.Abs(start-57.1f)<.01&&s.Clock==56,"failed try gives opponent dead ball spot and one runoff");s=Try(3);s.Snap();Call(s,"EndPlay",30f,"INCOMPLETE",true);start=(float)typeof(Simulation).GetField("opponentStart",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s);Check(s.State==Phase.Opponent&&s.Clock==60&&start==70,"incomplete fails try at own thirty without runoff");s=Try(4);s.Snap();s.ThrowAway();for(int i=0;i<100&&s.State==Phase.Flight;i++)s.Update(.02f,0,0);Check(s.State==Phase.Opponent&&!s.OnsideAttempt,"throwaway also loses the one-play attempt");
  foreach(int quarter in new int[]{1,2,3,4}){s=new Simulation(quarter);s.Quarter=quarter;s.HomeScore=35;s.AwayScore=0;Check(s.RequestOnsideTry(),"try allowed while leading in quarter "+quarter);}
  s=Try(5);s.Snap();Call(s,"ScoreTouchdown");Check(s.HomeScore==6&&s.State==Phase.Conversion&&!s.OnsideAttempt&&s.OnsideConversions==1,"long onside play can score normally");s.ChooseConversion(false);s.KickMeter=.5f;s.StopKick();for(int i=0;i<44;i++)s.Update(.05f,0,0);Check(s.HomeScore==7&&s.State==Phase.Kickoff,"PAT leads to kickoff choice");clock=s.Clock;for(int i=0;i<100;i++)s.Update(.05f,0,0);Check(s.State==Phase.Kickoff&&s.Clock==clock,"kickoff waits without simulating opponent drive");s.NormalKickoff();Check(s.State==Phase.Opponent,"normal kickoff gives opponent possession");
  s=new Simulation(6);s.Spot=80;s.FieldGoal();s.KickMeter=.5f;s.StopKick();for(int i=0;i<44;i++)s.Update(.05f,0,0);Check(s.HomeScore==3&&s.State==Phase.Kickoff&&s.RequestOnsideTry(),"made field goal offers onside try");s.CancelOnsideTry();Check(s.State==Phase.Kickoff&&!s.OnsideRulesPending&&s.CanOnsideTry,"back from explanation preserves kickoff choice");s.NewGame();Check(!s.OnsideRulesShown&&!s.OnsideAttempt&&s.OnsideAttempts==0,"new game resets one-time explanation and attempt state");s.Practice=true;Check(!s.RequestOnsideTry(),"practice cannot abandon rep for onside attempt");s.Practice=false;Call(s,"ScoreTouchdown");s.ChooseConversion(true);Check(!s.RequestOnsideTry(),"cannot replace two-point try with onside attempt");
  Console.WriteLine("Onside: "+checks+" checks, "+failures+" failures");return failures;
 }
}
}
